mapper.select:
select
teacher.*,
types.type_name
from teacher teacher
left join types types on teacher.type_id = types.id
left join teacher_subject  s on s.teacher_id = teacher.id

    and teacher.id = #{id}
    and teacher.name like concat('%',#{name},'%')
    and teacher.age = #{age}
    and teacher.sex = #{sex}
    and teacher.username = #{username}
    and teacher.password = #{password}
    and teacher.head_img = #{headImg}
    and teacher.collegiate = #{collegiate}
    and teacher.educational = #{educational}
    and teacher.educational_img = #{educationalImg}
    and teacher.info = #{info}
    and teacher.status = #{status}
    and teacher.create_time = #{createTime}
    and teacher.email like concat('%',#{email},'%')
    and teacher.type_id = #{typeId}
    and types.type_name like concat('%',#{typeName},'%')
    and s.subject_id in (${ids}) 

group by s.teacher_id

    limit #{current},#{pageSize}

select count(DISTINCT teacher.id) from teacher teacher
left join types types on teacher.type_id = types.id
left join teacher_subject  s on s.teacher_id = teacher.id

    and teacher.id = #{id}
    and teacher.name like concat('%',#{name},'%')
    and teacher.age = #{age}
    and teacher.sex = #{sex}
    and teacher.username = #{username}
    and teacher.password = #{password}
    and teacher.head_img = #{headImg}
    and teacher.collegiate = #{collegiate}
    and teacher.educational = #{educational}
    and teacher.educational_img = #{educationalImg}
    and teacher.info = #{info}
    and teacher.status = #{status}
    and teacher.create_time = #{createTime}
    and teacher.email like concat('%',#{email},'%')
    and teacher.type_id = #{typeId}
    and types.type_name like concat('%',#{typeName},'%')
    and s.subject_id in (${ids})
